-- Contrato canônico V2 da pontuação final normalizada.
-- Escopo: materializa somente as 613 linhas que já estavam explicitamente
-- publicadas na V1. Não inicia fila, não escolhe outra Build e não publica
-- nenhuma linha nova.
begin;

create function clube_novo.calcular_pontuacao_normalizada_v2(
  p_atributos_finais jsonb,
  p_arows_snapshot jsonb
)
returns numeric
language sql
immutable
strict
parallel safe
set search_path = ''
as $$
  with linhas as (
    select
      (item->>0)::integer as indice,
      (item->>1)::numeric as peso,
      (item->>2)::numeric as alvo
    from jsonb_array_elements(p_arows_snapshot) item
  ), parcelas as (
    select
      sum(peso * (p_atributos_finais->>indice)::numeric) as numerador,
      sum(peso * alvo) as denominador
    from linhas
    where peso <> 0
  )
  select case when denominador > 0
    then 100 * numerador / denominador
    else null::numeric
  end
  from parcelas
$$;

revoke all on function clube_novo.calcular_pontuacao_normalizada_v2(jsonb, jsonb)
  from public, anon, authenticated;
grant execute on function clube_novo.calcular_pontuacao_normalizada_v2(jsonb, jsonb)
  to service_role;

comment on function clube_novo.calcular_pontuacao_normalizada_v2(jsonb, jsonb) is
  'Equação imutável V2 executada dentro do clube_novo: 100 * soma(peso * atributo final) / soma(peso * alvo), sem a régua bruta do Otimizador.';

create table clube_novo.build_pontuacao_normalizada_v2 (
  linha_id bigint primary key
    references clube_novo.build_linha_card(id) on delete restrict,
  build_otimizador_id bigint not null unique
    references clube_novo.build_otimizador(id) on delete restrict,
  build_bonificador_id bigint not null
    references clube_novo.build_bonificador(id) on delete restrict,
  contrato text not null default 'clube-novo-overall-normalizado-v2'
    check (contrato = 'clube-novo-overall-normalizado-v2'),
  otimizador_resultado_fingerprint text not null
    check (otimizador_resultado_fingerprint ~ '^[0-9a-f]{64}$'),
  bonificador_resultado_fingerprint text not null
    check (bonificador_resultado_fingerprint ~ '^[0-9a-f]{64}$'),
  carta_fingerprint text not null
    check (carta_fingerprint ~ '^[0-9a-f]{64}$'),
  formula_fingerprint text not null
    check (formula_fingerprint ~ '^[0-9a-f]{64}$'),
  contrato_fingerprint text not null
    check (contrato_fingerprint ~ '^[0-9a-f]{64}$'),
  atributos_finais jsonb not null
    check (jsonb_typeof(atributos_finais) = 'array'
      and jsonb_array_length(atributos_finais) = 26),
  arows_snapshot jsonb not null
    check (jsonb_typeof(arows_snapshot) = 'array'
      and jsonb_array_length(arows_snapshot) = 26),
  numerador numeric not null,
  denominador numeric not null check (denominador > 0),
  pontuacao_normalizada_recomputada_evidencia numeric not null,
  pontuacao_otimizador_bruta_selada numeric not null,
  pontuacao_otimizador_bruta_recalculada numeric not null,
  bonus_total_bonificador numeric not null,
  overall_final_recomputado_evidencia numeric not null,
  pontuacao_otimizador_normalizada numeric generated always as
    (clube_novo.calcular_pontuacao_normalizada_v2(
      atributos_finais, arows_snapshot)) stored,
  overall_final numeric generated always as
    (clube_novo.calcular_pontuacao_normalizada_v2(
      atributos_finais, arows_snapshot) + bonus_total_bonificador) stored,
  normalizacao_fingerprint text not null unique
    check (normalizacao_fingerprint ~ '^[0-9a-f]{64}$'),
  publicacao_v2_fingerprint text,
  publicacao_fingerprint_v1 text not null
    check (publicacao_fingerprint_v1 ~ '^[0-9a-f]{64}$'),
  publicada_em_v1 timestamp with time zone not null,
  calculada_em timestamp with time zone not null default statement_timestamp(),
  check (pontuacao_otimizador_bruta_recalculada = pontuacao_otimizador_bruta_selada),
  check (abs(pontuacao_normalizada_recomputada_evidencia
    - pontuacao_otimizador_normalizada)
    <= 0.000000000001),
  check (abs(overall_final_recomputado_evidencia - overall_final)
    <= 0.000000000001)
);

comment on table clube_novo.build_pontuacao_normalizada_v2 is
  'Evidência privada e imutável da recomposição controlada das Builds V1 já publicadas. A régua bruta permanece apenas como prova de seleção; o front-end recebe o overall normalizado mais o bônus selado.';

alter table clube_novo.build_pontuacao_normalizada_v2 enable row level security;
revoke all on clube_novo.build_pontuacao_normalizada_v2
  from public, anon, authenticated;
grant usage on schema clube_novo to service_role;
grant select on clube_novo.build_pontuacao_normalizada_v2 to service_role;

create temporary table _build_pontuacao_normalizada_v2_source
on commit drop
